"""Lightweight source scanner for unpinned GitHub Actions ``uses`` values."""
import re


_SHA = re.compile(r"^[0-9a-fA-F]{40}$")


def detect_unpinned_uses(text):
    """Return ``(line_number, value)`` pairs for remotely referenced unpinned uses.

    Line numbers are 1-based. Local actions and Docker images are excluded.
    """
    found = []
    for number, line in enumerate(text.splitlines(), 1):
        m = re.match(r"^\s*uses\s*:\s*(.*?)\s*(?:#.*)?$", line)
        if not m:
            continue
        value = m.group(1).strip().strip("\"'")
        if not value or value.startswith("./") or value.startswith("docker://"):
            continue
        if "@" not in value:
            # Remote actions without a ref are invalid/implicitly unpinned too.
            found.append((number, value))
            continue
        ref = value.rsplit("@", 1)[1]
        if not _SHA.fullmatch(ref):
            found.append((number, value))
    return found
"""Output helpers for zizmor-compatible formats."""
import json
import os


def _primary(finding):
    locs = finding.get("locations") or []
    for loc in locs:
        if (loc.get("symbolic") or {}).get("kind") == "Primary":
            return loc
    return locs[-1] if locs else {}


def _where(finding):
    loc = _primary(finding)
    sym = loc.get("symbolic") or {}
    key = sym.get("key") or {}
    local = key.get("Local") or {}
    path = local.get("given_path") or ""
    concrete = loc.get("concrete") or {}
    location = concrete.get("location") or {}
    start = location.get("start_point") or {}
    return path, int(start.get("row", 0)) + 1, sym.get("annotation") or ""


def github(findings):
    out = []
    for f in findings:
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        ident = f.get("ident", "finding")
        desc = f.get("desc", ident)
        msg = os.path.basename(path) + ":" + str(line) + ": " + desc
        if annotation:
            msg += ": " + annotation
        props = []
        if path:
            props.append("file=" + path.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A").replace(":", "%3A").replace(",", "%2C"))
        props += ["line=" + str(line), "title=" + ident]
        level = str((f.get("determinations") or {}).get("severity", "medium")).lower()
        cmd = "error" if level == "high" else "warning" if level == "medium" else "notice"
        out.append("::" + cmd + " " + ",".join(props) + "::" + msg.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A"))
    return "\n".join(out) + ("\n" if out else "")


def sarif(findings):
    """Render a compact SARIF 2.1.0 report from JSON-v1-shaped findings."""
    rules, results = {}, []
    for f in findings:
        ident = f.get("ident", "finding")
        url, desc = f.get("url", ""), f.get("desc", ident)
        rid = "zizmor/" + ident
        rules.setdefault(rid, {"id": rid, "name": ident, "helpUri": url,
            "help": {"text": desc, "markdown": "`" + ident + "`: " + desc + ("\n\nDocs: <" + url + ">" if url else "")},
            "properties": {"tags": ["security"]}})
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        locs = []
        for item in f.get("locations") or []:
            sym = item.get("symbolic") or {}
            con = item.get("concrete") or {}
            pos = con.get("location") or {}
            start, end = pos.get("start_point") or {}, pos.get("end_point") or {}
            k = (sym.get("key") or {}).get("Local") or {}
            p = k.get("given_path") or path
            a = sym.get("annotation") or ""
            physical = {"artifactLocation": {"uri": p}}
            if pos:
                physical["region"] = {"startLine": int(start.get("row", 0))+1,
                    "startColumn": int(start.get("column", 0))+1,
                    "endLine": int(end.get("row", start.get("row", 0)))+1,
                    "endColumn": int(end.get("column", start.get("column", 0)))+1,
                    "sourceLanguage": "yaml"}
                if con.get("feature") is not None:
                    physical["region"]["snippet"] = {"text": con["feature"]}
            logical = {"logicalLocations": [{"properties": {"symbolic": sym}}], "physicalLocation": physical}
            if a:
                logical["message"] = {"text": a}
            locs.append(logical)
        primary = next((x for x in locs if ((x.get("logicalLocations", [{}])[0].get("properties", {}).get("symbolic") or {}).get("kind") == "Primary")), None)
        if primary is None and locs:
            primary = locs[-1]
        det = f.get("determinations") or {}
        result = {"ruleId": rid, "kind": "fail", "level": "error" if det.get("severity") == "High" else "warning",
            "message": {"text": desc + (": " + annotation if annotation else "")},
            "properties": {"zizmor/confidence": det.get("confidence", "Medium"), "zizmor/persona": det.get("persona", "Regular"), "zizmor/severity": det.get("severity", "Medium")}}
        if primary:
            result["locations"] = [primary]
            result["codeFlows"] = [{"threadFlows": [{"locations": [{"importance": "essential" if x is primary else "important", "location": x} for x in locs]}]}]
        results.append(result)
    return {"$schema": "https://docs.oasis-open.org/sarif/sarif/v2.1.0/os/schemas/sarif-schema-2.1.0.json",
        "runs": [{"invocations": [{"executionSuccessful": True}], "results": results,
                 "tool": {"driver": {"name": "zizmor", "version": "1.25.2", "semanticVersion": "1.25.2",
                    "informationUri": "https://docs.zizmor.sh", "downloadUri": "https://github.com/zizmorcore/zizmor",
                    "rules": list(rules.values())}}}], "version": "2.1.0"}


def format_output(kind, findings):
    if kind == "github":
        return github(findings)
    if kind == "sarif":
        return json.dumps(sarif(findings), indent=2, ensure_ascii=False)
    raise ValueError("unsupported output format: " + kind)
"""Small standard-library helpers for zizmor configuration and suppressions."""
import os
import re


def parse_config(text):
    """Parse the intentionally small rules subset of zizmor.yml."""
    rules, current, section = {}, None, None
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip())
        s = line.strip()
        if indent == 0 and s == "rules:":
            section = "rules"; continue
        if indent == 2 and s.endswith(":"):
            current = s[:-1].strip().strip("\"'")
            rules[current] = {"ignore": []}
            section = "rules"
            continue
        if section != "rules" and section not in ("ignore", "remap"):
            continue
        if current is None:
            continue
        if indent >= 4 and s.startswith("disable:"):
            rules[current]["disable"] = s.split(":", 1)[1].strip().lower() in ("true", "yes")
        elif indent >= 4 and s.startswith("ignore:"):
            section = "ignore"
        elif indent == 6 and s.startswith("-") and section == "ignore":
            val = s[1:].strip().strip("\"'")
            if val: rules[current]["ignore"].append(val)
        elif indent == 4 and s.startswith("remap:"):
            section = "remap"
        elif indent >= 6 and s.startswith("severity:") and section == "remap":
            rules[current].setdefault("remap", {})["severity"] = s.split(":", 1)[1].strip().strip("\"'")
        elif indent <= 2:
            section = "rules"
    return {"rules": rules}


def _rule_config(config, ident):
    return (config or {}).get("rules", {}).get(ident, {})


def _matches(rule, filename, line, col):
    parts = rule.rsplit(":", 2)
    name = parts[0]
    if os.path.basename(filename) != name:
        return False
    try:
        rline = int(parts[1]) if len(parts) > 1 else None
        rcol = int(parts[2]) if len(parts) > 2 else None
    except ValueError:
        return False
    return (rline is None or rline == line) and (rcol is None or rcol == col)


def apply_config(findings, config=None, path="", source="", no_ignores=False):
    """Filter disabled audits, mark ignored results, and apply severity remaps."""
    lines = source.splitlines()
    out = []
    for original in findings:
        finding = dict(original)
        ident = finding.get("ident", "")
        rule = _rule_config(config, ident)
        if rule.get("disable") is True:
            continue
        remap = rule.get("remap", {}).get("severity")
        if remap and isinstance(finding.get("determinations"), dict):
            finding["determinations"] = dict(finding["determinations"])
            finding["determinations"]["severity"] = remap.title()
        ignored = bool(finding.get("ignored", False))
        if not no_ignores:
            for loc in finding.get("locations", []):
                point = loc.get("concrete", {}).get("location", {}).get("start_point", {})
                line, col = point.get("row", 0) + 1, point.get("column", 0) + 1
                if any(_matches(x, path, line, col) for x in rule.get("ignore", [])):
                    ignored = True
                # Ignore annotations are YAML comments; accept common inline and preceding forms.
                lo = max(0, line - 2); hi = min(len(lines), line + 1)
                for text in lines[lo:hi]:
                    m = re.search(r"zizmor:\s*ignore\[([^]]+)\]", text)
                    if m and ("*" in m.group(1).split(",") or ident in [x.strip() for x in m.group(1).split(",")]):
                        ignored = True
            finding["ignored"] = ignored
        out.append(finding)
    return out

