"""Offline Dependabot audit rules, using source-line parsing only."""
import re

URL = "https://docs.zizmor.sh/audits/#"


def _location(path, line_no, line, annotation, route, kind="Primary"):
    # Rows and columns in the JSON interface are zero based; offsets are bytes.
    start = sum(len(x.encode("utf-8")) for x in path["text"].splitlines(keepends=True)[:line_no])
    feature = line.rstrip("\r\n")
    leading = len(feature) - len(feature.lstrip(" "))
    # A sequence item's dash is not part of the YAML key's source span.
    if re.match(r"\s*-\s+package-ecosystem\s*:", feature):
        keypos = feature.index("package-ecosystem")
        column = keypos
        start += len(feature[:keypos].encode("utf-8"))
        shown = feature[keypos:]
    else:
        column = leading
        start += len(feature[:leading].encode("utf-8"))
        shown = feature[leading:]
    end = start + len(shown.encode("utf-8"))
    key = {"Stdin": {}} if path.get("path") in ("-", "<stdin>") else {"File": {"path": path.get("path", "")}}
    return {
        "symbolic": {"key": key, "annotation": annotation,
                     "route": {"route": [{"Key": k} if isinstance(k, str) else {"Index": k} for k in route]},
                     "feature_kind": "Normal", "kind": kind},
        "concrete": {"location": {"start_point": {"row": line_no, "column": column},
                                   "end_point": {"row": line_no, "column": column + len(shown)},
                                   "offset_span": {"start": start, "end": end}},
                     "feature": shown, "comments": []}}


def audit_dependabot(record, days=7, persona="Regular"):
    """Return JSON-schema finding dictionaries for a Dependabot YAML record."""
    text = record.get("text", "")
    lines = text.splitlines(keepends=True)
    record = dict(record)
    record["text"] = text
    # Dependabot updater blocks start at a sequence item under `updates:`.
    blocks = []
    start = None
    for i, line in enumerate(lines):
        if re.match(r"\s*updates\s*:", line):
            start = i + 1
            break
    if start is None:
        return []
    items = []
    for i in range(start, len(lines)):
        line = lines[i]
        if line.strip() and not line.lstrip().startswith("#") and len(line) - len(line.lstrip()) == 0:
            break
        if re.match(r"\s*-\s+package-ecosystem\s*:", line):
            items.append(i)
    if not items:
        # Also permit the dash and package-ecosystem key on separate lines.
        items = [i for i in range(start, len(lines)) if re.match(r"\s*-\s*$", lines[i])]
    for n, first in enumerate(items):
        stop = items[n + 1] if n + 1 < len(items) else len(lines)
        # End at another top-level key.
        for j in range(first + 1, stop):
            if lines[j].strip() and not lines[j].lstrip().startswith("#") and len(lines[j]) - len(lines[j].lstrip()) <= 2:
                stop = j
                break
        block = list(range(first, stop))
        eco_line = next((j for j in block if re.search(r"package-ecosystem\s*:", lines[j])), None)
        if eco_line is None:
            continue
        ecosystem = re.search(r"package-ecosystem\s*:\s*[\"']?([^\s\"'#]+)", lines[eco_line])
        ecosystem = ecosystem.group(1) if ecosystem else ""
        # These ecosystems do not support Dependabot cooldown.
        if ecosystem in {"docker", "github-actions", "gitsubmodule", "terraform", "devcontainers", "helm"}:
            continue
        p = {"Key": "updates"}
        # Locate item index by order within updates.
        idx = items.index(first)
        ep = p | {"Index": idx}
        ecop = ["updates", idx, "package-ecosystem"]
        cooldown = next((j for j in block if re.match(r"\s*cooldown\s*:", lines[j])), None)
        exec_line = next((j for j in block if re.match(r"\s*insecure-external-code-execution\s*:\s*allow\b", lines[j])), None)
        if exec_line is not None:
            locations = [_location(record, exec_line, lines[exec_line], "enabled here", ["updates", idx, "insecure-external-code-execution"]),
                         _location(record, eco_line, lines[eco_line], "this ecosystem", ecop, "Related")]
            blocks.append({"ident":"dependabot-execution", "desc":"external code execution in Dependabot updates",
                "url":URL+"dependabot-execution", "determinations":{"confidence":"High","severity":"High","persona":persona},
                "locations":locations,"ignored":False})
        cooldown_line = None
        if cooldown is not None:
            for j in block:
                if j > cooldown and re.match(r"\s{0,}\S", lines[j]) and len(lines[j])-len(lines[j].lstrip()) <= len(lines[cooldown])-len(lines[cooldown].lstrip()):
                    break
                if j > cooldown and re.match(r"\s*default-days\s*:", lines[j]):
                    cooldown_line = j
                    break
        if cooldown_line is None:
            blocks.append({"ident":"dependabot-cooldown", "desc":"insufficient cooldown in Dependabot updates",
                "url":URL+"dependabot-cooldown", "determinations":{"confidence":"High","severity":"Medium","persona":persona},
                "locations":[_location(record,eco_line,lines[eco_line],"missing cooldown configuration",ecop)],"ignored":False})
        else:
            m = re.search(r"default-days\s*:\s*(\d+)", lines[cooldown_line])
            if m and int(m.group(1)) < days:
                blocks.append({"ident":"dependabot-cooldown", "desc":"insufficient cooldown in Dependabot updates",
                    "url":URL+"dependabot-cooldown", "determinations":{"confidence":"Medium","severity":"Low","persona":persona},
                    "locations":[_location(record,cooldown_line,lines[cooldown_line],f"insufficient default-days configured (less than {days})",["updates",idx,"cooldown","default-days"])],"ignored":False})
    return blocks
"""Small offline source detector for template injection in Actions run blocks."""
import re


_EXPR = re.compile(r"\$\{\{\s*(.*?)\s*\}\}")
_KNOWN_SAFE = {
    "github.sha", "github.workflow", "github.workflow_ref",
    "github.workflow_sha", "github.run_id", "github.run_number",
    "github.run_attempt", "github.repository", "github.repository_id",
    "github.repository_owner", "github.repository_owner_id",
}


def detect_template_injection(text, persona="regular"):
    """Return ``(line_number, expression)`` for suspicious expansions in run blocks.

    The scanner deliberately works on source lines so callers can attach the
