"""Detect block-scalar ``if`` values with fenced expressions and trailing LF."""
import re


def detect_unsound_condition(text):
    """Return 1-based line numbers for suspect ``if: |`` / ``if: >`` fields."""
    lines = text.splitlines()
    results = []
    for i, line in enumerate(lines):
        m = re.match(r"^(\s*)if\s*:\s*([|>])([+-]?)(?:\s*(?:#.*)?)$", line)
        if not m or "-" in m.group(3):
            continue
        base = len(m.group(1))
        for j in range(i + 1, len(lines)):
            candidate = lines[j]
            if not candidate.strip():
                continue
            indent = len(candidate) - len(candidate.lstrip())
            if indent <= base:
                break
            if "${{" in candidate and "}}" in candidate:
                results.append((i + 1, j + 1))
                break
    return results

