    if unsafe_fixes: summary_parts.append(f"{unsafe_fixes} unsafe fixes")
    if summary_parts: summary += f" ({', '.join(summary_parts)})"
    print(summary + f": {counts['informational']} informational, {counts['low']} low, {counts['medium']} medium, {counts['high']} high")


def invalid_option(value, option, values):
    print(f"error: invalid value '{value}' for '{option}'\n  [possible values: {', '.join(values)}]\n\nFor more information, try '--help'.", file=sys.stderr)
    return 2


def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    # clap models --fix as an optional equals-only value; argparse would eat
    # the following positional input when nargs='?'.
    argv=['--fix=safe' if x == '--fix' else x for x in argv]
    handled,out,err,status=cli_extra.handle(argv)
    if handled:
      sys.stdout.write(out);sys.stderr.write(err);return status
    if '-h' in argv or '--help' in argv:
      print(Path(__file__).with_name('docs').joinpath('snippets/help.txt').read_text(),end='');return 0
    if not argv:
      print('error: the following required arguments were not provided:\n  <INPUT>...\n\nUsage: executable <INPUT>...\n\nFor more information, try \'--help\'.',file=sys.stderr)
      return 2
    p=argparse.ArgumentParser(add_help=False)
    p.add_argument('inputs',nargs='*');p.add_argument('--format',default='plain');p.add_argument('--collect',default='default');p.add_argument('--strict-collection',action='store_true')
    p.add_argument('--persona',default='pedantic' if '-p' in argv or '--pedantic' in argv else 'regular');p.add_argument('-p','--pedantic',action='store_true')
    p.add_argument('--min-severity',default='informational');p.add_argument('--min-confidence',default='low');p.add_argument('--no-exit-codes',action='store_true');p.add_argument('--no-config',action='store_true')
    p.add_argument('--offline','-o',action='store_true');p.add_argument('--no-online-audits',action='store_true');p.add_argument('--no-ignores',action='store_true')
    p.add_argument('--fix',nargs='?',const='safe');p.add_argument('--color',default='auto');p.add_argument('--no-progress',action='store_true');p.add_argument('-v',action='count',default=0);p.add_argument('-q',action='count',default=0)
    # Ignore unimplemented options that do not affect offline behavior.
    p.add_argument('--config');p.add_argument('--cache-dir');p.add_argument('--gh-token');p.add_argument('--gh-hostname',default='github.com');p.add_argument('--render-links',default='auto');p.add_argument('--show-audit-urls',default='auto')
    try: a, unknown=p.parse_known_args(argv)
    except SystemExit as e:return int(e.code)
    if unknown:
      print('error: unexpected argument: '+unknown[0],file=sys.stderr);return 2
    value_options=[(a.format,'--format <KIND>',('plain','json','json-v1','sarif','github')),
      (a.persona,'--persona <PERSONA>',('auditor','pedantic','regular')),
      (a.min_severity,'--min-severity <LEVEL>',('informational','low','medium','high')),
      (a.min_confidence,'--min-confidence <LEVEL>',('low','medium','high')),
      (a.color,'--color <WHEN>',('auto','always','never')),
      (a.render_links,'--render-links <WHEN>',('auto','always','never')),
      (a.show_audit_urls,'--show-audit-urls <WHEN>',('auto','always','never'))]
    for value, option, values in value_options:
      if value not in values: return invalid_option(value,option,values)
    if a.fix not in (None,'safe','unsafe-only','all'):
      return invalid_option(a.fix,'--fix[=<MODE>]',('safe','unsafe-only','all'))
    if not a.inputs:
      print("error: the following required arguments were not provided:\n  <INPUT>...\n\nUsage: executable [OPTIONS] <INPUT>...\n\nFor more information, try '--help'.",file=sys.stderr)
      return 2
    kinds=a.collect.replace(' ','').split(',')
    allowed={'all','default','workflows','actions','dependabot','workflows-only','actions-only'}
    bad=next((k for k in kinds if k not in allowed),None)
    if bad:
      print(f"error: invalid value '{bad}' for '--collect <KIND>...'\n  [possible values: all, default, workflows, actions, dependabot]\n\nFor more information, try '--help'.",file=sys.stderr)
      return 2
    for old,new in [('workflows-only','workflows'),('actions-only','actions')]:
      if old in kinds:
        print(f' WARN zizmor: --collect={old} is deprecated; use --collect={new} instead',file=sys.stderr)
        print(' WARN zizmor: future versions of zizmor will reject this mode',file=sys.stderr)
    if '-' in a.inputs and len(a.inputs) != 1:
      print(' INFO zizmor: 🌈 zizmor v1.25.2',file=sys.stderr)
      print('error: `-` (stdin) cannot be combined with other inputs\n\nUsage: zizmor [OPTIONS] <INPUT>...\n\nFor more information, try \'--help\'.',file=sys.stderr)
      return 2
    if a.q == 0:
      print(' INFO zizmor: 🌈 zizmor v1.25.2',file=sys.stderr)
    stdin=sys.stdin.read() if '-' in a.inputs else None
    normalized_kinds=['workflows' if k=='workflows-only' else 'actions' if k=='actions-only' else k for k in kinds]
    records,invalid=input_collection.collect(a.inputs,normalized_kinds,stdin)
    if invalid:
      print('fatal: no audit was performed',file=sys.stderr)
      for item in invalid: print('invalid input: '+item,file=sys.stderr)
      return 1
    parsed=[]
    for rec in records:
      syntax=flow_error(rec.text)
      if syntax:
        if a.strict_collection:
          uri=Path(rec.path).resolve().as_uri() if rec.path != '<stdin>' else 'stdin:'
          input_kind={'actions':'action','workflows':'workflow','dependabot':'Dependabot config'}.get(rec.kind,'workflow')
          print('fatal: no audit was performed',file=sys.stderr)
          print(f'failed to load {uri} as {input_kind}',file=sys.stderr)
          print(f'\nCaused by:\n    0: invalid YAML syntax: {syntax}\n    1: {syntax}',file=sys.stderr)
          return 1
        print(f' WARN collect_inputs: zizmor::registry::input: failed to parse input: {syntax}',file=sys.stderr)
        continue
      parsed.append(rec)
    records=parsed
    if not records:
      print('fatal: no audit was performed\nerror: no inputs collected\n  |\n  = help: collection yielded no auditable inputs\n  = help: inputs must contain at least one valid workflow, action, or Dependabot config\n\nCaused by:\n    no inputs collected',file=sys.stderr)
      return 3
    global_config = None
    if not a.no_config:
      cfgpath = a.config or os.environ.get('ZIZMOR_CONFIG')
      if cfgpath:
        if not os.path.isfile(cfgpath):
          print('invalid config: '+cfgpath,file=sys.stderr);return 1
        try: global_config=config_support.parse_config(Path(cfgpath).read_text())
        except OSError:
          print('invalid config: '+cfgpath,file=sys.stderr);return 1
    findings=[]
    for rec in records:
      cfg=global_config
      if cfg is None and not a.no_config:
        cfgpath=config_support.discover_config(rec.path)
        if cfgpath:
          try: cfg=config_support.parse_config(Path(cfgpath).read_text())
          except OSError: cfg=None
      current=audit(rec,'pedantic' if a.pedantic else a.persona,cfg)
      findings += config_support.apply_config(current,cfg,rec.path,rec.text,True,rec.kind)
    fix_counts, held_back = apply_fixes(records, findings, a.fix) if a.fix else ({}, 0)
    if a.q == 0:
      for rec in records:
        print(f' INFO audit: zizmor: 🌈 completed {rec.path}',file=sys.stderr)
    order={'informational':0,'low':1,'medium':2,'high':3}; conf={'low':0,'medium':1,'high':2}
    findings=[f for f in findings if order.get(f['determinations']['severity'].lower(),0)>=order.get(a.min_severity,0) and conf.get(f['determinations']['confidence'].lower(),0)>=conf.get(a.min_confidence,0)]
    audit_order={'unsound-contains':-1,'artipacked':0,'excessive-permissions':1,'dangerous-triggers':2,'bot-conditions':3,
                 'template-injection':4,'unpinned-uses':5,'unsound-condition':6,
                 'self-hosted-runner':7,'anonymous-definition':8,'concurrency-limits':9}
    findings.sort(key=lambda f:audit_order.get(f.get('ident'),100))
    if a.format in ('json','json-v1'):
      emitted=findings if a.no_ignores else [f for f in findings if not f.get('ignored')]
      print(json.dumps(emitted,indent=2,ensure_ascii=False))
    elif a.format == 'plain':
      unsafe_fixes=sum(1 for f in findings
        if f.get('ident') in ('artipacked','template-injection') and (a.no_ignores or not f.get('ignored')))
      plain(findings, {r.path:r.text for r in records},a.no_ignores,unsafe_fixes)
    elif a.format in ('sarif','github'):
      emitted=findings if a.no_ignores else [f for f in findings if not f.get('ignored')]
      out=format_output(a.format,emitted)
      print(json.dumps(out,indent=2,ensure_ascii=False) if isinstance(out,dict) else out,end='' if str(out).endswith('\n') else '\n')
    if a.fix:
      if fix_counts:
        print(f"\nFix Summary\nSuccessfully applied fixes to {len(fix_counts)} files:", file=sys.stderr)
        for path in sorted(fix_counts):
          print(f"  {path}: {fix_counts[path]} fixes", file=sys.stderr)
      elif held_back:
        print(f'No fixes available to apply ({held_back} held back by safe mode). Use --fix=unsafe-only or --fix=all to apply unsafe fixes.',file=sys.stderr)
      else:
        print('No fixes available to apply.',file=sys.stderr)
    active=findings if a.no_ignores else [f for f in findings if not f.get('ignored')]
    if not active or a.format == 'sarif' or a.no_exit_codes: return 0
    highest=max((order.get(f['determinations']['severity'].lower(),0) for f in active),default=0)
    return 11 + highest

if __name__=='__main__': raise SystemExit(main())

